 return dict(level_id=level,metric=metric,unit=unit,statistic='sample_maximum',scope='entire region-v1; explicitly sampled sourcegeometry, not global proven bound',source_ids=sourceids,coverage_evidence=ref(evidence),sampling_plan=ref('data/sampling-plan.json'),samples=[float(x)for x in vals],reported_value=float(max(vals)),unsampled_limitations=limitations)
